  "noticeClose": "Tárolási tájékoztató bezárása",
  "privDraftLabel": "Tervezet – frissítve: 2026. október 28.",
  "privDraft": "A fiókfunkciók tesztelés alatt állnak. Az alábbi üzemeltetői és szolgáltatói adatokat a nyilvános indulás előtt ki kell egészíteni.",
  "privWho1": "A Cook üzemeltetője: [az üzemeltető hivatalos neve és postacíme]. Adatvédelmi kérdésekkel és kérelmekkel a [adatvédelmi e-mail-cím] címen fordulhatsz hozzánk. Ezeket az adatokat a regisztráció megnyitása előtt ki kell egészíteni.",
  "privWhat1": "Amikor fiókot hozol létre, az e-mail-címedet, egy fiókazonosítót, a jelszavas hitelesítés adatait és a megerősítés állapotát használjuk a fiókod biztosításához és védelméhez. A jelszavakat a hitelesítési szolgáltató biztonságos hash formájában kezeli; a Cook nem tárol olvasható jelszavakat. Tároljuk a konyha elrendezését, a választott nyelvet, a témát és a mértékegységeket, hogy a beállításaidat minden eszközödön visszaállíthassuk. A fiókhoz e-mail-cím és jelszó szükséges; a recepteket fiók nélkül is böngészheted.",
  "privWhat2": "A fiók és a beállítások kezelése az általad kért fiókszolgáltatás nyújtásához szükséges (GDPR 6. cikk (1) bekezdés b) pont). Korlátozott biztonsági és visszaélés-megelőzési adatokat jogos érdek alapján (6. cikk (1) bekezdés f) pont) kezelhetünk, a szükséges mértékben és érdekmérlegelés után. A megerősítő és jelszó-visszaállító e-mailek szolgáltatási üzenetek, nem marketing. A fiókfunkció nem ad hozzá hirdetést vagy elemzést.",
  "privStorage1": "A Cook a sessionStorage-et használja arra, hogy a konyhádat, a főzés állását és a választásaidat ugyanazon a lapon belül az oldalak között átvigye. Bejelentkezve ez a bejelentkezési munkamenetedet is tárolja. A böngésző ezt általában törli, amikor a lap munkamenete véget ér, de a böngésző munkamenet-visszaállítása megőrizheti. Kijelentkezéskor a Cook lapadatai törlődnek. A tárolási tájékoztató bezárását csak az adott lap jegyzi meg. A Cook saját szkriptjei nem állítanak be sütiket. A tárhely- vagy szolgáltatóid saját biztonsági adatkezelést végezhetnek, amelyet az indulás előtt dokumentálni kell.",
  "privStorage2": "Az OK és a tárolási tájékoztató bezárás gombja csak bezárja a tájékoztatót. Nem engedélyeznek elemzést, hirdetést vagy más opcionális követést. Bármilyen jövőbeli, nem szükséges tárolás előtt külön választás szükséges, amelyben az elutasítás és a visszavonás ugyanolyan egyszerű.",
  "privOther1": "A receptlista jelenlegi beszédfunkciója az IP-címed alapján egy hozzávetőleges országot kér le a country.is szolgáltatástól, hogy kiválassza a beszédfelismerés nyelvét. Ha mikrofonos felismerést használsz, a böngésződ a hangot elküldheti a saját beszédfelismerő szolgáltatójának. A hozzávalókat be is gépelheted. Ezeket a szolgáltatókat, irányelveiket és a funkciók jogalapját a nyilvános indulás előtt felül kell vizsgálni.",
  "privProviders1": "Tervezett fiókszolgáltató: Supabase (felügyelt PostgreSQL és hitelesítés), kiválasztott EU-s adatbázisrégióval. E-mail-szolgáltató: [szolgáltató]. Webtárhely: [szolgáltató]. Az üzemeltetőnek meg kell erősítenie a tényleges szolgáltatókat, az adatfeldolgozási szerződéseket, az alvállalkozó adatfeldolgozókat, a naplók helyét és az EGT-n kívülre irányuló esetleges adattovábbítást. Egy EU-s adatbázisrégió önmagában nem zárja ki a nemzetközi adattovábbítást. Adott esetben meg kell nevezni az alkalmazandó megfelelőségi határozatot vagy szerződéses garanciákat, és azt, hogyan kérhető belőlük másolat.",
  "privRetention1": "A fiókbeállításokat addig őrizzük, amíg a fiókod aktív. A törlést a fenti adatvédelmi elérhetőségen kérheted. Az indulás előtt az üzemeltetőnek meg kell határoznia a törlési kérelmek kezelésének menetét, a meg nem erősített fiókok lejáratát, valamint a biztonsági naplók és a biztonsági mentések megőrzési idejét. A törölt adatok a dokumentált megőrzési idő végéig korlátozott hozzáférésű biztonsági mentésekben maradhatnak.",
  "privRights1": "Az alkalmazandó feltételektől függően kérheted az adatokhoz való hozzáférést, helyesbítést, törlést, korlátozást vagy adathordozhatóságot, illetve tiltakozhatsz a jogos érdeken alapuló adatkezelés ellen. Fordulj a fenti üzemeltetőhöz; a kérelmekre általában egy hónapon belül válaszolunk, és az esetleges jogszerű határidő-hosszabbítást megindokoljuk. Panaszt tehetsz a felügyeleti hatóságnál, többek között a magyar NAIH-nál (naih.hu). A Cook nem használja a fiókbeállításokat joghatással vagy hasonlóan jelentős hatással járó automatizált döntésekhez.",
