  "Let it cool until warm or at room temperature (that is how it is eaten) and scatter over the rest of the parsley.": "Hagyd langyosra vagy szobahőmérsékletűre hűlni (így eszik), és szórd meg a maradék petrezselyemmel.",
  "Warm or room temperature": "Langyos vagy szobahőmérsékletű",
  "Peel in stripes · Chop the filling": "Hámozd csíkosra · Vágd fel a tölteléket",
  "Fry the eggplants · Cook the filling": "Süsd meg a padlizsánokat · Készítsd el a tölteléket",
  "with chili": "chilivel",
  "juiced": "kifacsart",
  "Peel and thinly slice the onions.": "Hámozd meg a hagymákat, és szeleteld vékonyra.",
  "Thin slices": "Vékony szeletek",
  "Make the marinade": "Készítsd el a pácot",
  "Mix the lemon juice, mustard, garlic, crumbled stock cube, pepper, salt and half the oil. Add the chicken and the onions and mix well.": "Keverd össze a citromlevet, a mustárt, a fokhagymát, a szétmorzsolt leveskockát, a borsot, a sót és az olaj felét. Add hozzá a csirkét és a hagymát, és keverd jól össze.",
  "Everything coated": "Minden bevonva",
  "Cover and marinate in the fridge for at least 1 hour (or overnight).": "Fedd le, és pácold a hűtőben legalább 1 órán át (vagy egy éjszakán át).",
  "Lift the chicken out of the marinade (keep the onions and the marinade) and brown it in the rest of the oil. Take it out.": "Vedd ki a csirkét a pácból (a hagymát és a pácot tedd félre), és pirítsd meg a maradék olajon. Vedd ki.",
  "Browned on both sides": "Mindkét oldala megpirult",
  "Cook the onions": "Párold meg a hagymát",
  "Fry the onions from the marinade in the same pan until soft and golden.": "Párold a pácolt hagymát ugyanabban a serpenyőben puhára és aranybarnára.",
  "Add the rest of the marinade, the water and the bay leaf (and the chili), put the chicken back, cover and simmer until the chicken is tender. Add the olives for the last 5 minutes.": "Add hozzá a maradék pácot, a vizet és a babérlevelet (és a chilit), tedd vissza a csirkét, fedd le, és párold, amíg a csirke puha. Az olívabogyót az utolsó 5 percre add hozzá.",
  "Chicken tender, onions jammy": "Csirke puha, hagyma lekvárszerű",
  "Serve the chicken and onions over the rice.": "Tálald a csirkét és a hagymát rizsen.",
  "Brown the chicken … Simmer": "Pirítsd meg a csirkét … Főzd lassú tűzön",
  "whole, pricked": "egész, megszurkálva",
  "Chicken, finely chopped": "Csirke, apróra vágva",
  "With a crispy fried egg": "Ropogós tükörtojással",
  "Pound the garlic and chilies": "Zúzd össze a fokhagymát és a chilit",
  "Pound the garlic and chilies to a rough paste in a mortar (or chop them finely).": "Zúzd durva pasztává a fokhagymát és a chilit mozsárban (vagy aprítsd finomra).",
  "Rough paste": "Durva paszta",
  "Mix the oyster sauce, both soy sauces, fish sauce, sugar and water.": "Keverd össze az osztrigaszószt, mindkét szójaszószt, a halszószt, a cukrot és a vizet.",
  "Heat the oil in the wok until very hot and fry the eggs one at a time, spooning hot oil over them, until the edges are crispy and the yolk is still runny. Keep them on a plate.": "Hevítsd fel erősen az olajat a wokban, és süsd ki a tojásokat egyenként, forró olajjal locsolgatva, amíg a szélük ropogós, a sárgájuk még folyós. Tedd őket félre egy tányérra.",
  "Crispy edges, runny yolk": "Ropogós szél, folyós sárgája",
  "Fry the garlic and chilies": "Pirítsd meg a fokhagymát és a chilit",
  "Heat the oil in the wok and fry the garlic and chili paste for a few seconds until fragrant.": "Hevítsd fel az olajat a wokban, és pirítsd a fokhagymás-chilis pasztát néhány másodpercig, amíg illatos lesz.",
  "Fragrant, not brown": "Illatos, nem barnult meg",
